import type { Result } from '../kernel/result.js';
import { err, ok } from '../kernel/result.js';
import { lookupOrder, markOrderRefunded } from './order.service.js';

export function refundOrder(orderId: string): Result<string, string> {
  const order = lookupOrder(orderId);

  if (!order) {
    return err(`Order ${orderId} not found`);
  }

  if (order.refunded) {
    return err(`Order ${orderId} has already been refunded`);
  }

  if (order.total < 10) {
    return err(`Order ${orderId} total of ${order.total} is below minimum refund amount of 10`);
  }

  markOrderRefunded(orderId);
  return ok(`Order ${orderId} refunded successfully`);
}

